-- currencies holds 40 rows on a single heap page
-- index: CREATE INDEX idx_currencies_code ON currencies (code);
SELECT * FROM currencies WHERE code = 'EUR';

-- index: CREATE INDEX idx_products_name ON products (name);
SELECT * FROM products WHERE name LIKE '%phone';   -- query 1
SELECT * FROM products WHERE name LIKE 'phone%';   -- query 2

-- 99% of orders have status = 'DONE'; 0.1% have status = 'FAILED'
-- index: CREATE INDEX idx_orders_status ON orders (status);
PREPARE q AS SELECT * FROM orders WHERE status = $1;
EXECUTE q('FAILED');

-- events: 20,000,000 rows, freshly ANALYZEd
-- index: CREATE INDEX idx_events ON events (tenant_id, created_at);
SELECT * FROM events
WHERE date_trunc('day', created_at) = DATE '2026-07-01';

